  ('physics-board-dhaka-2017-mcq-025', 'class9-physics-bn-guide', 'satt-physics-board.pdf p236', 'm ভরের বস্তুকে R থেকে মুক্তভাবে পড়তে দিলে— i. বস্তুটিতে গতি সঞ্চার হবে ii. গতিশক্তি বিভব শক্তিতে রূপান্তরিত হবে iii. অতিক্রান্ত দূরত্ব বাড়লে বেগ বাড়বে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'physics-board-dhaka-2017-mcq', false, 'board-mcq', null, null, 'dhaka', 2017, true),
