  ('physics-board-dhaka-2019-mcq-003', 'class9-physics-bn-guide', 'satt-physics-board.pdf p203', 'A ও B আহিত বস্তুর ক্ষেত্রে- i. A গোলক থেকে কিছু আধান B গোলকে যাবে ii. A গোলক থেকে বলরেখা B গোলকে যাবে iii. দুটি গোলকের বিভব সমান না হওয়া পর্যন্ত আধানের এই প্রবাহ চলবে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"ii","গ":"i ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-dhaka-2019-mcq', false, 'board-mcq', null, null, 'dhaka', 2019, true),
