  ('physics-board-dhaka-2020-mcq-007', 'class9-physics-bn-guide', 'satt-physics-board.pdf p175', 'কোনো পরিবাহীর দুই প্রান্তের বিভব পার্থক্য 220 V এবং তড়িৎ প্রবাহ 20 A হলে রোধ কত?', 'mcq', '{"ক":"240 Ω","খ":"220 Ω","গ":"11 Ω","ঘ":"0.0909 Ω"}'::jsonb, 'গ', 1, false, 'physics-board-dhaka-2020-mcq', false, 'board-mcq', null, null, 'dhaka', 2020, true),
